@* Displays a single task card with title, assignee, priority badge, due date, and move buttons *@

<div class="task-card">
    <div class="task-card-header">
        <span class="task-title">@Task.Title</span>
        <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    </div>
    <div class="task-card-body">
        <span class="task-assignee">@Task.Assignee</span>
        <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    </div>
    <div class="task-card-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="() => OnMoveLeft.InvokeAsync(Task.Id)" disabled="@IsMoving">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="() => OnMoveRight.InvokeAsync(Task.Id)" disabled="@IsMoving">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public bool IsMoving { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
}

@* Inline form for creating a new task within a column *@

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="Title" />
    <input type="text" placeholder="Assignee" @bind="Assignee" />
    <select @bind="Priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="DueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@IsSaving">Save</button>
        <button class="btn-cancel" @onclick="HandleCancel" disabled="@IsSaving">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = default!;
    [Parameter] public EventCallback<NewTaskModel> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string Title { get; set; } = string.Empty;
    private string Assignee { get; set; } = string.Empty;
    private string Priority { get; set; } = "Medium";
    private DateTime DueDate { get; set; } = DateTime.Today.AddDays(7);
    private bool IsSaving { get; set; }

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(Title)) return;

        IsSaving = true;
        await OnSave.InvokeAsync(new NewTaskModel(Title.Trim(), Assignee.Trim(), Priority, DueDate));
        IsSaving = false;

        // Reset form
        Title = string.Empty;
        Assignee = string.Empty;
        Priority = "Medium";
        DueDate = DateTime.Today.AddDays(7);
    }

    private async Task HandleCancel()
    {
        await OnCancel.InvokeAsync();
    }

    public record NewTaskModel(string Title, string Assignee, string Priority, DateTime DueDate);
}

@* A single Kanban column displaying its tasks and an add-task form *@

<div class="kanban-column">
    <div class="kanban-column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>

    <div class="kanban-column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      IsMoving="IsMoving"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>

    <div class="kanban-column-footer">
        @if (_showForm)
        {
            <AddTaskForm DefaultStatus="@ColumnName"
                         OnSave="HandleSave"
                         OnCancel="() => _showForm = false" />
        }
        else
        {
            <button class="btn-add-task" @onclick="() => _showForm = true">+ Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public bool IsMoving { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskModel> OnAddTask { get; set; }

    private bool _showForm;

    private async Task HandleSave(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync(model);
        _showForm = false;
    }
}

@* Search bar for filtering tasks by title *@

<div class="task-search-bar">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Project Board</h2>

@if (_loading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (_error is not null)
{
    <div class="error-message">
        <p>Error: @_error</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Total="@_allTasks.Count"
                ToDoCount="@GetTasksForStatus("To Do").Count"
                InProgressCount="@GetTasksForStatus("In Progress").Count"
                DoneCount="@GetTasksForStatus("Done").Count"
                OverdueCount="@_allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <TaskSearchBar SearchText="@_searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="@GetFilteredTasksForStatus("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      IsMoving="@_isMoving"
                      OnMoveRight="(id) => MoveTask(id, \"In Progress\")"
                      OnAddTask="(model) => AddTask(model, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="@GetFilteredTasksForStatus("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      IsMoving="@_isMoving"
                      OnMoveLeft="(id) => MoveTask(id, \"To Do\")"
                      OnMoveRight="(id) => MoveTask(id, \"Done\")"
                      OnAddTask="(model) => AddTask(model, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="@GetFilteredTasksForStatus("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      IsMoving="@_isMoving"
                      OnMoveLeft="(id) => MoveTask(id, \"In Progress\")"
                      OnAddTask="(model) => AddTask(model, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> _allTasks = new();
    private string _searchText = string.Empty;
    private bool _loading = true;
    private string? _error;
    private bool _isMoving;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        _loading = true;
        _error = null;

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void HandleSearchChanged(string text)
    {
        _searchText = text;
    }

    private List<TaskItem> GetTasksForStatus(string status)
    {
        return _allTasks.Where(t => t.Status == status).ToList();
    }

    private List<TaskItem> GetFilteredTasksForStatus(string status)
    {
        var tasks = _allTasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
        }

        return tasks.ToList();
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        _isMoving = true;

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                _allTasks.Remove(task);
                _allTasks.Add(task with { Status = newStatus });
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _isMoving = false;
        }
    }

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            _allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}

