{"path": "/tmp/sv-32357743cc2d4931b67a276f15a7f351/Components/Pages/Board/KanbanBoard.razor", "file_text": "@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Project Board</h2>

@if (_loading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (_error is not null)
{
    <div class="error-message">
        <p>Error: @_error</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Total="@_allTasks.Count"
                ToDoCount="@GetTasksForStatus("To Do").Count"
                InProgressCount="@GetTasksForStatus("In Progress").Count"
                DoneCount="@GetTasksForStatus("Done").Count"
                OverdueCount="@_allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <TaskSearchBar SearchText="@_searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="@GetFilteredTasksForStatus("To Do")"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      IsMoving="@_isMoving"
                      OnMoveRight="(id) => MoveTask(id, \"In Progress\")"
                      OnAddTask="(model) => AddTask(model, \"To Do\")" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="@GetFilteredTasksForStatus("In Progress")"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      IsMoving="@_isMoving"
                      OnMoveLeft="(id) => MoveTask(id, \"To Do\")"
                      OnMoveRight="(id) => MoveTask(id, \"Done\")"
                      OnAddTask="(model) => AddTask(model, \"In Progress\")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="@GetFilteredTasksForStatus("Done")"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      IsMoving="@_isMoving"
                      OnMoveLeft="(id) => MoveTask(id, \"In Progress\")"
                      OnAddTask="(model) => AddTask(model, \"Done\")" />
    </div>
}

@code {
    private List<TaskItem> _allTasks = new();
    private string _searchText = string.Empty;
    private bool _loading = true;
    private string? _error;
    private bool _isMoving;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        _loading = true;
        _error = null;

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void HandleSearchChanged(string text)
    {
        _searchText = text;
    }

    private List<TaskItem> GetTasksForStatus(string status)
    {
        return _allTasks.Where(t => t.Status == status).ToList();
    }

    private List<TaskItem> GetFilteredTasksForStatus(string status)
    {
        var tasks = _allTasks.Where(t => t.Status == status);

        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
        }

        return tasks.ToList();
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        _isMoving = true;

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                _allTasks.Remove(task);
                _allTasks.Add(task with { Status = newStatus });
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _isMoving = false;
        }
    }

    private async Task AddTask(AddTaskForm.NewTaskModel model, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            _allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}
"}

